using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ObscureEffect", menuName = "Data/Battle/Effects/Enemy/Obscure Effect")]
public class ObscureEffect : Effect
{
	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return base.localizationManager.GetLocalizedAfterFirstCantSeeMeterBase(GetLocalizedDescription());
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		SpawnVFX(GetVFXOwnerPosition(effectOwner));
		PlayEffectActivationSFX();
		return effectAmount;
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.CurrentTurnAreaTurnsBattles.Count > 0 && ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.CurrentBattle.BattleTurnCounter >= 2)
		{
			effectOwner.GetComponent<CorruptedAnimalEffects>().ToggleHideOverCorruption(value: true);
		}
	}
}
